		if dep.DependsOnTask != nil {
			label = fmt.Sprintf("%s (%s)", dep.DependsOnTask.Title, dep.DependsOnTask.Status)
		}
		out.Dependencies = append(out.Dependencies, label)
	}
	for _, gitRef := range detail.GitRefs {
